const body = $input.first().json.body || $input.first().json;
let employees = body?.data?.source?.itens || body?.data?.employees || [];

if (!Array.isArray(employees) || employees.length === 0) {
  return [{ _valid: false, error: 'Missing or empty employees array' }];
}

const formatCpf = (cpf) => {
  if (!cpf) return '';
  const cleaned = String(cpf).replace(/\D/g, '');
  return cleaned.length === 11 ? cleaned.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4') : cpf;
};

const parseDate = (d) => {
  if (!d || d === "") return null;
  const ts = parseInt(d);
  if (!isNaN(ts)) {
    const date = new Date(ts * 1000);
    return isNaN(date.getTime()) ? null : date.toISOString().split('T')[0];
  }
  const date = new Date(d);
  return isNaN(date.getTime()) ? null : date.toISOString().split('T')[0];
};

const parseSalary = (s) => {
  if (!s) return 0;
  return parseFloat(String(s).replace(/[^0-9.,]/g, '').replace(',', '.')) || 0;
};

return employees.map(emp => {
  return {
    _valid: true,
    nome_funcionario: String(emp.Nome || '').trim(),
    matricula: String(emp.Matricula || '').trim(),
    cargo: String(emp.Cargo || '').trim(),
    cbo: String(emp.CBO || '').trim(),
    rg: String(emp.Rg || '').trim(),
    cpf: formatCpf(emp.CPF),
    data_nascimento: parseDate(emp.DataNascimento),
    salario: parseSalary(emp.Salario),
    data_admissao: parseDate(emp.DataAdmissao),
    data_demissao: parseDate(emp.DataDemissao),
    status: String(emp.Status || '').trim(),
    data_cadastro: parseDate(emp.DataCad),
    data_modificacao: parseDate(emp.DataMod),
    departamento: String(emp.Depto || '').trim()
  };
});
